  const total = S.inventory.reduce((sum, item) => sum + saleValue(item), 0);
  const items = S.inventory.length
    ? S.inventory.map((item) => `
      <div class="item-card">
        <span class="item-glyph">▤</span>
        <span>
          <span class="item-name">${esc(item.name)}</span>
